import { toast } from "sonner";
import {
  Area, AreaChart, Bar, BarChart, CartesianGrid, Cell, ComposedChart, Line, LineChart,
  Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis,
} from "recharts";

const navItems = [
  { id: "dashboard", label: "Executive dashboard", icon: LayoutDashboard, group: "Monitor" },
  { id: "signatures", label: "Electric signature", icon: Activity, group: "Monitor" },
  { id: "anomalies", label: "Anomaly intelligence", icon: ShieldAlert, group: "Monitor" },
  { id: "energy", label: "Energy intelligence", icon: Zap, group: "Monitor" },
  { id: "network", label: "Network hierarchy", icon: GitBranch, group: "Network" },
  { id: "transformers", label: "Transformers", icon: Bolt, group: "Network" },
  { id: "feeders", label: "Feeders & sections", icon: Layers3, group: "Network" },
  { id: "map", label: "Live network map", icon: MapPinned, group: "Network" },
  { id: "alerts", label: "Alert centre", icon: Bell, group: "Operate" },
  { id: "simulation", label: "Simulation centre", icon: BrainCircuit, group: "Operate" },
  { id: "reports", label: "Reports", icon: FileText, group: "Operate" },
  { id: "settings", label: "Settings", icon: Settings2, group: "System" },
] as const;
type Language = "en" | "ta";
type LanguageState = { language: Language; setLanguage: (language: Language) => void };
const LanguageContext = createContext<LanguageState>({ language: "en", setLanguage: () => undefined });
function useLanguage() { return useContext(LanguageContext); }
function LanguageProvider({ children }: { children: React.ReactNode }) {
  const [language, setLanguage] = useState<Language>("en");
  return <LanguageContext.Provider value={{ language, setLanguage }}>{children}</LanguageContext.Provider>;
}
const navLabels: Record<NavId, [string, string]> = {
  dashboard: ["Executive dashboard", "முக்கியக் கண்காணிப்பு பலகை"],
  signatures: ["Electric signature", "மின் கையொப்பம்"],
  anomalies: ["Anomaly intelligence", "முரண்பாடு நுண்ணறிவு"],
  energy: ["Energy intelligence", "ஆற்றல் நுண்ணறிவு"],
  network: ["Network hierarchy", "வலையமைப்பு படிநிலை"],
  transformers: ["Transformers", "மின்மாற்றிகள்"],
  feeders: ["Feeders & sections", "ஊட்டிகள் மற்றும் பகுதிகள்"],
  map: ["Live network map", "நேரடி வலையமைப்பு வரைபடம்"],
  alerts: ["Alert centre", "எச்சரிக்கை மையம்"],
  simulation: ["Simulation centre", "உருவகப்படுத்தல் மையம்"],
  reports: ["Reports", "அறிக்கைகள்"],
  settings: ["Settings", "அமைப்புகள்"],
};
const groupLabels: Record<string, [string, string]> = { Monitor: ["Monitor", "கண்காணிப்பு"], Network: ["Network", "வலையமைப்பு"], Operate: ["Operate", "செயல்பாடு"], System: ["System", "அமைப்பு"] };
function getNavLabel(id: NavId, language: Language) { return navLabels[id][language === "ta" ? 1 : 0]; }
function getGroupLabel(group: string, language: Language) { return (groupLabels[group] ?? [group, group])[language === "ta" ? 1 : 0]; }

type NavId = (typeof navItems)[number]["id"];

type Severity = "LOW" | "MEDIUM" | "HIGH" | "CRITICAL";
type Anomaly = {
  id: string; timestamp: string; location: string; type: string; deviation: number; anomalyScore: number; risk: number;
  confidence: number; severity: Severity; status: "Investigation Required" | "Acknowledged" | "Resolved";
  description: string; causes: string[]; recommendation: string;
};
type Summary = {
  systemOnline: boolean; simulated: boolean; networkHealth: number; substations: number; transformers: number;
  feeders: number; sections: number; activeAnomalies: number; criticalAlerts: number; energyImbalance: number;
  energySupplied: number; energyAccounted: number; lastUpdated: string; mode: string; activeAnomaly: Anomaly | null;
  hardware: { connected: boolean; device: string; lastSeen: string };
};
type Node = {
  id: string; kind: "substation" | "transformer" | "feeder" | "section"; name: string; location: string;
  parent?: string; latitude: number; longitude: number; status: "normal" | "warning" | "critical";
  voltage: number; current: number; power: number; load: number; risk: number;
};
type TrendPoint = { time: string; baseline: number; actual: number; load: number };
type SimScenario = "normal" | "abnormal-load" | "potential-theft" | "meter-anomaly" | "transformer-anomaly" | "night-consumption" | "energy-imbalance";
type SignatureFeature = { key: string; label: string; baseline: number; current: number; unit: string; delta: number };

const tooltipStyle = { background: "#0d1d28", border: "1px solid rgba(142,185,196,.2)", borderRadius: 10, color: "#e8f0f5", fontSize: 11 };
const fmt = (value: number) => new Intl.NumberFormat("en-IN").format(value);
const timeAgo = (iso: string) => new Date(iso).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });

function severityClass(severity: Severity | string) {
  return severity === "CRITICAL" ? "text-[#ff8a8a] bg-[#ff6868]/10 border-[#ff6868]/25" : severity === "HIGH" ? "text-[#ffc477] bg-[#ffad4a]/10 border-[#ffad4a]/25" : severity === "MEDIUM" ? "text-[#f4d58b] bg-[#dbc15a]/10 border-[#dbc15a]/25" : "text-[#84e3bb] bg-[#54d49b]/10 border-[#54d49b]/25";
}
function dotClass(status: Node["status"]) { return status === "critical" ? "bg-[#ff6b6b] shadow-[0_0_0_5px_rgba(255,107,107,.12)]" : status === "warning" ? "bg-[#f5b65a] shadow-[0_0_0_5px_rgba(245,182,90,.12)]" : "bg-[#5ee6d0] shadow-[0_0_0_4px_rgba(94,230,208,.09)]"; }

function Panel({ children, className = "", title, subtitle, action }: { children: React.ReactNode; className?: string; title?: string; subtitle?: string; action?: React.ReactNode }) {
  return <section className={`gov-panel gov-energy-line rounded-xl border border-white/[.08] bg-[#0b1822]/90 panel-shine ${className}`}>
    {(title || action) && <div className="flex items-start justify-between gap-4 border-b border-white/[.07] px-5 py-4"><div><h2 className="text-[13px] font-bold tracking-wide text-[#dceaf0]">{title}</h2>{subtitle && <p className="mt-1 text-[11px] text-[#76909d]">{subtitle}</p>}</div>{action}</div>}
    {children}
  </section>;
}
function StatusChip({ children, tone = "cyan" }: { children: React.ReactNode; tone?: "cyan" | "amber" | "red" | "green" }) {
  const tones = { cyan: "text-[#7cebd9] bg-[#5ee6d0]/10 border-[#5ee6d0]/20", amber: "text-[#ffcb85] bg-[#ffb454]/10 border-[#ffb454]/25", red: "text-[#ff9a9a] bg-[#ff6b6b]/10 border-[#ff6b6b]/25", green: "text-[#8ce6ba] bg-[#62d99b]/10 border-[#62d99b]/25" };
  return <span className={`inline-flex items-center gap-1.5 rounded-md border px-2 py-1 text-[10px] font-bold tracking-[.12em] ${tones[tone]}`}>{children}</span>;
}
function MetricCard({ label, value, suffix, icon: Icon, note, tone = "cyan", progress }: { label: string; value: string | number; suffix?: string; icon: LucideIcon; note: string; tone?: "cyan" | "amber" | "red" | "green"; progress?: number }) {
  const colors = { cyan: "#5ee6d0", amber: "#ffbc69", red: "#ff7777", green: "#77e0a5" };
  return <div className="gov-data-card gov-energy-line relative overflow-hidden rounded-xl border border-white/[.08] bg-[#0c1c27] p-4 panel-shine"><div className="absolute -right-7 -top-7 h-20 w-20 rounded-full opacity-[.08] blur-2xl" style={{ background: colors[tone] }} /><div className="flex items-start justify-between"><span className="text-[10px] font-bold uppercase tracking-[.14em] text-[#718d99]">{label}</span><Icon size={15} style={{ color: colors[tone] }} /></div><div className="mt-3 flex items-baseline gap-1"><span className="mono text-[26px] font-medium tracking-[-.07em] text-[#e8f4f4]">{value}</span>{suffix && <span className="text-[12px] text-[#7c9aa2]">{suffix}</span>}</div><div className="mt-2 flex items-center gap-2 text-[10px] text-[#829ba3]"><span className="h-1.5 w-1.5 rounded-full" style={{ background: colors[tone] }} />{note}</div>{progress !== undefined && <div className="mt-3 h-1 overflow-hidden rounded-full bg-[#19303a]"><div className="h-full rounded-full" style={{ width: `${progress}%`, background: colors[tone] }} /></div>}</div>;
}
function Gauge({ value, label, size = 132 }: { value: number; label: string; size?: number }) {
  const radius = 45; const circumference = 2 * Math.PI * radius; const dash = circumference * value / 100;
  return <div className="relative" style={{ width: size, height: size }}><svg viewBox="0 0 110 110" className="h-full w-full -rotate-90"><circle cx="55" cy="55" r={radius} fill="none" stroke="#19313b" strokeWidth="8" /><circle cx="55" cy="55" r={radius} fill="none" stroke={value >= 80 ? "#ff6b6b" : value >= 60 ? "#ffb454" : "#5ee6d0"} strokeWidth="8" strokeLinecap="round" strokeDasharray={`${dash} ${circumference - dash}`} /></svg><div className="absolute inset-0 flex flex-col items-center justify-center"><span className="mono text-[22px] font-medium text-white">{value}</span><span className="text-[9px] uppercase tracking-[.14em] text-[#79939e]">{label}</span></div></div>;
}

function Sidebar({ activeNav, onNavigate, open, onClose }: { activeNav: NavId; onNavigate: (id: NavId) => void; open: boolean; onClose: () => void }) {
  const { language } = useLanguage();
  const groups = ["Monitor", "Network", "Operate", "System"];
  return <><div onClick={onClose} className={`fixed inset-0 z-40 bg-black/60 lg:hidden ${open ? "block" : "hidden"}`} /><aside className={`fixed inset-y-0 left-0 z-50 flex w-[264px] flex-col border-r border-white/[.08] bg-[#07141d] transition-transform duration-200 lg:static lg:z-auto lg:translate-x-0 ${open ? "translate-x-0" : "-translate-x-full"}`}>
    <div className="flex h-[74px] items-center justify-between border-b border-white/[.07] px-5"><div className="flex items-center gap-3"><div className="esi-wordmark" aria-label="ESI"><span>ESI</span></div><div className="esi-brand-lockup"><div className="esi-brand-title">ESI</div><div className="esi-brand-subtitle">Electric Signature Intelligence</div></div></div><button onClick={onClose} className="rounded-md p-1.5 text-[#6f8a94] hover:bg-white/5 lg:hidden"><X size={16} /></button></div>
    <div className="mx-4 mt-4 flex items-center gap-2 rounded-lg border border-[#5ee6d0]/15 bg-[#5ee6d0]/[.06] px-3 py-2"><span className="pulse-dot h-2 w-2 rounded-full bg-[#5ee6d0]" /><div><div className="text-[10px] font-bold text-[#a9eee1]">SYSTEM ONLINE</div><div className="mono text-[9px] text-[#668892]">SIMULATED NETWORK</div></div><Radio size={13} className="ml-auto text-[#5ee6d0]" /></div>
    <nav className="mt-5 flex-1 overflow-y-auto px-3 pb-4">{groups.map((group) => <div key={group} className="mb-4"><div className="mb-2 px-3 text-[9px] font-bold uppercase tracking-[.2em] text-[#4f707b]">{getGroupLabel(group, language)}</div>{navItems.filter((item) => item.group === group).map((item) => { const active = item.id === activeNav; const Icon = item.icon; return <button key={item.id} onClick={() => { onNavigate(item.id); onClose(); }} className={`group flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-left text-[11px] font-semibold transition-colors ${active ? "bg-[#5ee6d0]/10 text-[#baf6ec] gov-nav-active" : "text-[#79929d] hover:bg-white/[.045] hover:text-[#c4d9df]"}`}><Icon size={15} className={active ? "text-[#5ee6d0]" : "text-[#607e88] group-hover:text-[#9db8bf]"} /><span>{getNavLabel(item.id, language)}</span>{active && <span className="ml-auto h-1.5 w-1.5 rounded-full bg-[#5ee6d0]" />}</button>; })}</div>)}</nav>
    <div className="border-t border-white/[.07] p-4"><div className="flex items-center gap-3 rounded-lg bg-white/[.03] p-3"><div className="grid h-8 w-8 place-items-center rounded-full bg-[#243c4b] text-[#9ee4da]"><UserRound size={14} /></div><div className="min-w-0"><div className="truncate text-[11px] font-bold text-[#cbdde2]">Demo operator</div><div className="truncate text-[9px] text-[#6d8892]">Control room · Analyst</div></div><ChevronDown size={14} className="ml-auto text-[#5f7d87]" /></div><div className="mt-3 flex items-center justify-between text-[9px] text-[#5c7b84]"><span className="flex items-center gap-1.5"><span className="h-1.5 w-1.5 rounded-full bg-[#65d99e]" /> API connected</span><span>v0.9.0-proto</span></div></div>
  </aside></>;
}

function Header({ activeNav, onMenu, anomalyCount }: { activeNav: NavId; onMenu: () => void; anomalyCount: number }) {
  const { language, setLanguage } = useLanguage();
  const item = navItems.find((nav) => nav.id === activeNav);
  return <header className="flex min-h-[74px] items-center justify-between gap-4 border-b border-white/[.07] bg-[#08151e]/90 px-4 py-3 backdrop-blur-md sm:px-6"><div className="flex items-center gap-3"><button onClick={onMenu} className="rounded-md p-2 text-[#89a3ac] hover:bg-white/5 lg:hidden"><Menu size={19} /></button><div><div className="flex items-center gap-2"><h1 className="text-[15px] font-extrabold tracking-[-.02em] text-[#e6f0f2]">{item ? getNavLabel(item.id, language) : "ESI"}</h1><span className="hidden rounded border border-[#5ee6d0]/20 bg-[#5ee6d0]/[.06] px-1.5 py-0.5 text-[9px] font-bold uppercase tracking-[.12em] text-[#79d9cc] sm:inline gov-live-signal">Live view</span></div><div className="mt-1 flex items-center gap-2 text-[10px] text-[#68838e]"><span>TN distribution prototype</span><span className="text-[#35505b]">/</span><span className="mono text-[#7899a4]">CHN-SUB-01</span></div></div></div><div className="flex items-center gap-2 sm:gap-3"><div className="hidden h-9 w-[170px] items-center gap-2 rounded-lg border border-white/[.08] bg-white/[.025] px-3 md:flex"><Search size={14} className="text-[#577680]" /><span className="text-[10px] text-[#5f7d87]">Search network...</span><span className="mono ml-auto rounded border border-white/10 px-1 text-[8px] text-[#5f7d87]">⌘K</span></div><button onClick={() => setLanguage(language === "en" ? "ta" : "en")} className="flex items-center gap-1.5 rounded-lg border border-[#1d63a9]/20 bg-[#1d63a9]/[.05] px-2.5 py-2 text-[10px] font-bold text-[#1d63a9]" aria-label="Change language"><span>{language === "en" ? "தமிழ்" : "English"}</span></button><button className="relative rounded-lg border border-white/[.08] p-2 text-[#7f9aa2] hover:bg-white/5"><Bell size={15} /><span className="absolute right-1 top-1 h-1.5 w-1.5 rounded-full bg-[#ff7c7c]" /></button><div className="hidden h-8 w-px bg-white/[.1] sm:block" /><div className="flex items-center gap-2"><div className="grid h-8 w-8 place-items-center rounded-full border border-[#5ee6d0]/25 bg-[#102b33] text-[#9beadd]"><span className="text-[11px] font-extrabold">DO</span></div><div className="hidden sm:block"><div className="text-[10px] font-bold text-[#c8d9dd]">Demo operator</div><div className="text-[9px] text-[#66828c]">{anomalyCount ? "Investigation active" : "Monitoring"}</div></div><div className="founder-signature hidden lg:flex"><span>FOUNDER</span><strong>THARUN KUMAR</strong></div></div></div></header>;
}

function DashboardSimulationLauncher({ active, onNavigate, onSimulate, busy }: { active: boolean; onNavigate: (id: NavId) => void; onSimulate: (scenario: SimScenario) => void; busy: boolean }) {
  const [open, setOpen] = useState(false);
  const scenarios: Array<{ id: SimScenario; label: string }> = [
    { id: "normal", label: "Normal Operation" }, { id: "abnormal-load", label: "Abnormal Load" }, { id: "potential-theft", label: "Potential Electricity Theft" }, { id: "meter-anomaly", label: "Potential Meter Tampering" }, { id: "transformer-anomaly", label: "Transformer Anomaly" }, { id: "night-consumption", label: "Unusual Night Consumption" }, { id: "energy-imbalance", label: "Energy Imbalance" },
  ];
  return <div className="relative"><button onClick={() => setOpen((value) => !value)} className={`flex items-center gap-2 rounded-lg px-3 py-2 text-[10px] font-extrabold tracking-[.08em] transition ${active ? "border border-[#ff6b6b]/30 bg-[#ff6b6b]/10 text-[#ffb0b0]" : "bg-[#5ee6d0] text-[#04100f]"}`}><BrainCircuit size={14} /> {active ? "ANOMALY ACTIVE" : "SIMULATE ANOMALY"}<ChevronDown size={13} className={open ? "rotate-180" : ""} /></button>{open && <div className="absolute right-0 top-11 z-30 w-[270px] rounded-xl border border-[#5ee6d0]/20 bg-[#0b1822] p-2 shadow-2xl"><div className="px-3 py-2 text-[9px] font-bold uppercase tracking-[.14em] text-[#6f939c]">Choose simulated scenario</div>{scenarios.map((scenario) => <button key={scenario.id} disabled={busy} onClick={() => { onSimulate(scenario.id); setOpen(false); }} className="flex w-full items-center justify-between rounded-lg px-3 py-2.5 text-left text-[10px] font-bold text-[#b9d0d3] transition hover:bg-[#5ee6d0]/[.08] hover:text-[#dff9f4]"><span>{scenario.label}</span>{scenario.id === "normal" ? <Check size={12} className="text-[#62d99b]" /> : <ArrowUpRight size={12} className="text-[#79d9cc]" />}</button>)}<button onClick={() => { onNavigate("simulation"); setOpen(false); }} className="mt-1 w-full rounded-lg border-t border-white/[.07] px-3 py-2.5 text-left text-[9px] font-bold uppercase tracking-[.1em] text-[#72d9cb]">Open simulation centre →</button></div>}</div>;
}

function Dashboard({ summary, live, network, anomalies, events, onNavigate, onSimulate, simulationBusy }: { summary: Summary; live: { voltage: number; current: number; power: number; load: number; history: TrendPoint[]; status: string; location: string; id: string }; network: { nodes: Node[] }; anomalies: Anomaly[]; events: Array<{ id: string; type: string; time: string; message: string }>; onNavigate: (id: NavId) => void; onSimulate: (scenario: SimScenario) => void; simulationBusy: boolean }) {
  const { language } = useLanguage();
  const mapNodes = network.nodes.filter((node) => ["CHN-SUB-01", "TR-07", "FDR-12", "SEC-31", "SEC-30", "CBE-SUB-02", "TR-12", "SEC-18"].includes(node.id));
  return <div className="space-y-5"><div className="flex flex-wrap items-end justify-between gap-3"><div><div className="flex items-center gap-2"><span className="mono text-[10px] text-[#61939b]">21 SEP 2026 · 14:36:28 IST</span><span className="h-1 w-1 rounded-full bg-[#5ee6d0]" /></div><h2 className="mt-1 text-[24px] font-extrabold tracking-[-.05em] text-[#edf7f6] sm:text-[28px]">{language === "ta" ? "வலையமைப்பு கட்டுப்பாட்டு மேலோட்டம்" : "NETWORK COMMAND OVERVIEW"}</h2><p className="mt-1 text-[11px] text-[#718d97]">{language === "ta" ? "வலையமைப்பின் இயல்பான மின் கையொப்பத்தை ESI கற்றுக்கொள்கிறது." : "Electric Signature Intelligence is learning the grid's normal rhythm."}</p></div><div className="flex flex-wrap items-center gap-2"><StatusChip tone="green"><span className="h-1.5 w-1.5 rounded-full bg-current" /> SYSTEM ONLINE</StatusChip><StatusChip><span className="h-1.5 w-1.5 rounded-full bg-current" /> SIMULATED DATA</StatusChip><DashboardSimulationLauncher active={Boolean(summary.activeAnomaly)} onNavigate={onNavigate} onSimulate={onSimulate} busy={simulationBusy} /></div></div>
    <div className="grid grid-cols-2 gap-3 xl:grid-cols-4"><MetricCard label={language === "ta" ? "வலையமைப்பு நிலை" : "Network health"} value={summary.networkHealth.toFixed(1)} suffix="%" icon={GaugeIcon} note={summary.activeAnomaly ? "degraded by active scenario" : "within normal operating band"} progress={summary.networkHealth} tone={summary.networkHealth < 80 ? "amber" : "cyan"} /><MetricCard label={language === "ta" ? "செயலில் உள்ள முரண்பாடுகள்" : "Active anomalies"} value={String(summary.activeAnomalies).padStart(2, "0")} icon={ShieldAlert} note={summary.activeAnomaly ? `${summary.activeAnomaly.type} · investigation` : "no active deviations"} tone={summary.activeAnomaly ? "red" : "green"} /><MetricCard label={language === "ta" ? "முக்கிய எச்சரிக்கைகள்" : "Critical alerts"} value={String(summary.criticalAlerts).padStart(2, "0")} icon={AlertTriangle} note={summary.criticalAlerts ? "immediate attention required" : "no critical alerts"} tone={summary.criticalAlerts ? "red" : "amber"} /><MetricCard label={language === "ta" ? "ஆற்றல் சமநிலையின்மை" : "Energy imbalance"} value={summary.energyImbalance.toFixed(1)} suffix="%" icon={Zap} note="supply vs accounted energy" tone={summary.energyImbalance > 8 ? "amber" : "cyan"} progress={Math.min(100, summary.energyImbalance * 5)} /></div>
    {summary.activeAnomaly && <div className="anomaly-live-banner flex flex-col gap-3 rounded-xl border border-[#ff6b6b]/30 bg-[#421f29]/70 p-4 sm:flex-row sm:items-center sm:justify-between"><div className="flex gap-3"><div className="grid h-9 w-9 shrink-0 place-items-center rounded-lg bg-[#ff6b6b]/15 text-[#ff9696]"><Bell size={17} /></div><div><div className="text-[11px] font-extrabold uppercase tracking-[.08em] text-[#ffb0b0]">SIMULATED ANOMALY DETECTED · INVESTIGATION REQUIRED</div><p className="mt-1 text-[10px] leading-5 text-[#e4b9b9]">Potential electrical anomaly detected in SEC-31. Electrical signature has significantly deviated from the learned normal operating pattern.</p></div></div><button onClick={() => onNavigate("anomalies")} className="whitespace-nowrap rounded-lg border border-[#ff6b6b]/25 bg-[#ff6b6b]/[.08] px-3 py-2 text-[10px] font-bold text-[#ffb7b7]">Review anomaly →</button></div>}
    <PowerCommandRibbon summary={summary} live={live} onNavigate={onNavigate} />
    <LeadershipReference />
    <div className="grid gap-5 xl:grid-cols-[minmax(0,1.55fr)_minmax(320px,.85fr)]"><Panel title={language === "ta" ? "நேரடி சுமை மின் கையொப்பம்" : "Live load signature"} subtitle="Section SEC-31 · current demand against learned baseline" action={<button onClick={() => onNavigate("signatures")} className="flex items-center gap-1 text-[10px] font-bold text-[#72d9cb] hover:text-[#a9f1e6]">Open analysis <ChevronRight size={13} /></button>}><div className="h-[275px] px-2 pb-2 pt-5 sm:h-[315px] sm:px-5"><ResponsiveContainer width="100%" height="100%"><ComposedChart data={live.history} margin={{ left: -20, right: 4, top: 8, bottom: 0 }}><defs><linearGradient id="actualFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#5ee6d0" stopOpacity={.27} /><stop offset="100%" stopColor="#5ee6d0" stopOpacity={0} /></linearGradient></defs><CartesianGrid stroke="rgba(142,185,196,.08)" vertical={false} /><XAxis dataKey="time" tick={{ fill: "#65838d", fontSize: 9 }} tickLine={false} axisLine={false} interval={3} /><YAxis yAxisId="power" tick={{ fill: "#65838d", fontSize: 9 }} tickLine={false} axisLine={false} domain={[4, 9]} /><YAxis yAxisId="load" orientation="right" tick={{ fill: "#65838d", fontSize: 9 }} tickLine={false} axisLine={false} domain={[0, 100]} /><Tooltip contentStyle={tooltipStyle} cursor={{ stroke: "rgba(94,230,208,.25)" }} /><Area yAxisId="power" type="monotone" dataKey="actual" stroke="#5ee6d0" strokeWidth={2} fill="url(#actualFill)" name="Current power" /><Line yAxisId="power" type="monotone" dataKey="baseline" stroke="#728993" strokeWidth={1.5} strokeDasharray="4 4" dot={false} name="Normal signature" /><Line yAxisId="load" type="monotone" dataKey="load" stroke="#f1b65e" strokeWidth={1.5} dot={false} name="Load %" /></ComposedChart></ResponsiveContainer></div><div className="flex flex-wrap gap-x-5 gap-y-2 border-t border-white/[.06] px-5 py-3 text-[10px] text-[#76919a]"><span className="flex items-center gap-2"><i className="h-1.5 w-5 rounded-full bg-[#5ee6d0]" />Current power</span><span className="flex items-center gap-2"><i className="h-px w-5 border-t border-dashed border-[#728993]" />Normal signature</span><span className="flex items-center gap-2"><i className="h-1.5 w-5 rounded-full bg-[#f1b65e]" />Load percentage</span></div></Panel><Panel title={language === "ta" ? "மின் கையொப்ப நிலை" : "Electric Signature status"} subtitle="AI model · Isolation Forest · prototype risk model"><div className="grid grid-cols-[auto_1fr] items-center gap-5 p-5"><Gauge value={summary.activeAnomaly?.risk ?? 12} label={summary.activeAnomaly ? summary.activeAnomaly.severity : "LOW RISK"} size={142} /><div className="min-w-0"><div className="flex items-center gap-2"><span className={`h-2 w-2 rounded-full ${summary.activeAnomaly ? "bg-[#ff7777]" : "bg-[#5ee6d0]"}`} /><span className="text-[12px] font-bold text-[#d3e3e6]">{summary.activeAnomaly ? "Signature deviation detected" : "Stable electric signature"}</span></div><p className="mt-2 text-[11px] leading-5 text-[#78939d]">{summary.activeAnomaly ? summary.activeAnomaly.description : "Voltage, current, power, load and time patterns are tracking the learned baseline."}</p><div className="mt-4 rounded-lg border border-white/[.07] bg-white/[.025] p-3"><div className="flex items-center justify-between text-[10px]"><span className="text-[#79939e]">Confidence indicator</span><span className="mono text-[#b8d9d9]">{summary.activeAnomaly ? `${Math.round(summary.activeAnomaly.confidence * 100)}%` : "96%"}</span></div><div className="mt-2 h-1 rounded-full bg-[#20333c]"><div className="h-full rounded-full bg-[#5ee6d0]" style={{ width: `${summary.activeAnomaly ? summary.activeAnomaly.confidence * 100 : 96}%` }} /></div></div></div></div><div className="grid grid-cols-2 border-t border-white/[.06]"><div className="border-r border-white/[.06] p-4"><div className="text-[9px] uppercase tracking-[.14em] text-[#65818b]">Current reading</div><div className="mono mt-2 text-[18px] text-[#dff4f1]">{live.power.toFixed(2)} <small className="text-[10px] text-[#78939d]">kW</small></div></div><div className="p-4"><div className="text-[9px] uppercase tracking-[.14em] text-[#65818b]">Deviation</div><div className="mono mt-2 text-[18px] text-[#dff4f1]">{summary.activeAnomaly?.deviation ?? 6}<small className="text-[10px] text-[#78939d]">%</small></div></div></div></Panel></div>
    <div className="grid gap-5 xl:grid-cols-[minmax(0,1.15fr)_minmax(0,.85fr)]"><Panel title="Network pulse" subtitle="Simulated topology · status by latest telemetry" action={<button onClick={() => onNavigate("map")} className="flex items-center gap-1 text-[10px] font-bold text-[#72d9cb]">Full map <ChevronRight size={13} /></button>}><div className="relative h-[280px] overflow-hidden grid-scan"><div className="absolute left-[12%] top-[48%] h-px w-[75%] bg-gradient-to-r from-[#5ee6d0]/10 via-[#5ee6d0]/40 to-[#5ee6d0]/10" /><div className="absolute left-[28%] top-[31%] h-[58%] w-px bg-gradient-to-b from-[#5ee6d0]/10 via-[#5ee6d0]/35 to-[#5ee6d0]/10" /><div className="absolute right-[26%] top-[24%] h-[66%] w-px rotate-[31deg] bg-gradient-to-b from-[#5ee6d0]/10 via-[#ffb454]/35 to-[#ff6b6b]/20" />{mapNodes.map((node, i) => { const positions = [[13,48],[29,30],[48,48],[68,69],[86,58],[31,77],[60,26],[86,82]]; const [left, top] = positions[i] ?? [50,50]; return <button onClick={() => onNavigate("map")} key={node.id} style={{ left: `${left}%`, top: `${top}%` }} className="absolute -translate-x-1/2 -translate-y-1/2 text-left"><span className={`relative block h-3 w-3 rounded-full ${dotClass(node.status)}`} />{node.id === "SEC-31" && <span className="absolute -left-2 -top-2 h-7 w-7 animate-ping rounded-full border border-[#ff6b6b]/25" />}<span className="mt-2 block whitespace-nowrap rounded bg-[#07131b]/85 px-1.5 py-1 text-[9px] font-bold text-[#98b7bd]">{node.id}</span></button>; })}<div className="absolute bottom-3 left-4 flex flex-wrap gap-3 rounded-lg border border-white/[.07] bg-[#08151e]/85 px-3 py-2 text-[9px] text-[#708b95]"><span className="flex items-center gap-1.5"><i className="h-1.5 w-1.5 rounded-full bg-[#5ee6d0]" />Normal</span><span className="flex items-center gap-1.5"><i className="h-1.5 w-1.5 rounded-full bg-[#f5b65a]" />Warning</span><span className="flex items-center gap-1.5"><i className="h-1.5 w-1.5 rounded-full bg-[#ff6b6b]" />Critical</span></div><div className="absolute right-4 top-3 rounded border border-[#ffb454]/20 bg-[#ffb454]/[.07] px-2 py-1 text-[9px] font-bold tracking-[.12em] text-[#f2c37a]">SIMULATED MAP</div></div></Panel><Panel title="Intelligence activity" subtitle="Latest events from the processing pipeline" action={<button onClick={() => onNavigate("alerts")} className="text-[10px] font-bold text-[#72d9cb]">View alerts</button>}><div className="divide-y divide-white/[.06]">{events.slice(0, 4).map((event) => <div key={event.id} className="flex gap-3 px-5 py-3.5"><div className={`mt-1 grid h-6 w-6 shrink-0 place-items-center rounded-md ${event.type === "SIMULATION" ? "bg-[#ffb454]/10 text-[#ffbd6b]" : event.type === "ANALYSIS" ? "bg-[#a984ff]/10 text-[#b99aff]" : "bg-[#5ee6d0]/10 text-[#74decf]"}`}><Activity size={12} /></div><div className="min-w-0"><p className="text-[10px] leading-4 text-[#b3c9cd]">{event.message}</p><span className="mono text-[9px] text-[#5e7b85]">{event.time} · {event.type}</span></div></div>)}</div></Panel></div>
    <div className="rounded-xl border border-[#5ee6d0]/15 bg-gradient-to-r from-[#0b252c] to-[#0b1822] p-4 sm:p-5"><div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between"><div className="flex gap-3"><div className="grid h-9 w-9 shrink-0 place-items-center rounded-lg bg-[#5ee6d0]/10 text-[#66dfcf]"><CircleHelp size={17} /></div><div><div className="text-[11px] font-bold text-[#bdebe4]">Prototype risk model</div><p className="mt-1 max-w-2xl text-[10px] leading-4 text-[#77959b]">Risk combines signature deviation, energy imbalance, historical deviation, load abnormality, repetition, and network context. Weights require validation with real utility data.</p></div></div><button onClick={() => onNavigate("simulation")} className="whitespace-nowrap rounded-lg border border-[#5ee6d0]/25 bg-[#5ee6d0]/[.08] px-3 py-2 text-[10px] font-bold text-[#a3eee4] hover:bg-[#5ee6d0]/[.14]">Open demo mode <ArrowUpRight size={13} className="ml-1 inline" /></button></div></div>
  </div>;
}

function SignaturePage({ signature, history }: { signature: { overallDeviation: number; risk: number; section: string; features: SignatureFeature[]; updatedAt: string }; history: TrendPoint[] }) {
  const { language } = useLanguage();
  return <div className="space-y-5"><div className="flex flex-wrap items-end justify-between gap-3"><div><div className="mono text-[10px] text-[#61939b]">SIGNATURE / SEC-31 / LIVE</div><h2 className="mt-1 text-[24px] font-extrabold tracking-[-.05em]">{language === "ta" ? "மின் கையொப்பப் பகுப்பாய்வு" : "Electric Signature Analysis"}</h2><p className="mt-1 text-[11px] text-[#718d97]">Compare current behaviour against the learned normal profile.</p></div><div className="flex items-center gap-2"><StatusChip>Isolation Forest</StatusChip><StatusChip tone="amber">Prototype model</StatusChip></div></div><div className="grid gap-5 xl:grid-cols-[minmax(0,1.4fr)_minmax(280px,.6fr)]"><Panel title="Signature comparison" subtitle="Normal signature vs current electrical behaviour"><div className="h-[330px] p-5"><ResponsiveContainer width="100%" height="100%"><LineChart data={history} margin={{ left: -18, right: 8, top: 10, bottom: 0 }}><CartesianGrid stroke="rgba(142,185,196,.08)" vertical={false} /><XAxis dataKey="time" tick={{ fill: "#65838d", fontSize: 9 }} tickLine={false} axisLine={false} interval={3} /><YAxis tick={{ fill: "#65838d", fontSize: 9 }} tickLine={false} axisLine={false} domain={[4, 9]} /><Tooltip contentStyle={tooltipStyle} /><Line type="monotone" dataKey="baseline" stroke="#8298a2" strokeDasharray="5 5" strokeWidth={2} dot={false} name="Normal signature" /><Line type="monotone" dataKey="actual" stroke="#5ee6d0" strokeWidth={2.5} dot={false} name="Current signature" /></LineChart></ResponsiveContainer></div><div className="flex gap-5 border-t border-white/[.06] px-5 py-3 text-[10px] text-[#76919a]"><span className="flex items-center gap-2"><i className="h-1.5 w-5 rounded-full bg-[#5ee6d0]" />Current signature</span><span className="flex items-center gap-2"><i className="h-px w-5 border-t border-dashed border-[#8298a2]" />Normal signature</span></div></Panel><Panel title="Deviation assessment" subtitle={`Section ${signature.section} · refreshed ${timeAgo(signature.updatedAt)}`}><div className="flex items-center gap-5 p-5"><Gauge value={signature.risk} label={signature.risk >= 60 ? "HIGH" : "LOW"} size={128} /><div><div className="text-[10px] uppercase tracking-[.14em] text-[#66838d]">Overall deviation</div><div className="mono mt-1 text-[29px] text-[#e5f2f0]">{signature.overallDeviation}<small className="text-[12px] text-[#78939d]">%</small></div><div className="mt-2 text-[10px] text-[#8a9fa4]">Measured across 5 signal families</div></div></div><div className="border-t border-white/[.06] p-5"><div className="mb-3 flex justify-between text-[10px]"><span className="text-[#78939d]">Risk calculation</span><span className="mono text-[#cae5e4]">{signature.risk}/100</span></div><div className="h-2 rounded-full bg-[#1b3039]"><div className="h-full rounded-full bg-gradient-to-r from-[#5ee6d0] via-[#ffbd68] to-[#ff6b6b]" style={{ width: `${Math.max(signature.risk, 12)}%` }} /></div><div className="mt-3 grid grid-cols-3 text-[9px] text-[#66828b]"><span>0 LOW</span><span className="text-center">30 MEDIUM</span><span className="text-right">80 CRITICAL</span></div></div></Panel></div><Panel title="Feature-level deviation" subtitle="Current values are compared with the normal electric signature window"><div className="overflow-x-auto"><table className="w-full min-w-[650px] text-left"><thead className="border-b border-white/[.06] text-[9px] uppercase tracking-[.15em] text-[#60808a]"><tr><th className="px-5 py-3 font-semibold">Parameter</th><th className="px-5 py-3 font-semibold">Normal baseline</th><th className="px-5 py-3 font-semibold">Current</th><th className="px-5 py-3 font-semibold">Delta</th><th className="px-5 py-3 font-semibold">Status</th></tr></thead><tbody className="divide-y divide-white/[.05]">{signature.features.map((feature) => <tr key={feature.key} className="text-[11px] text-[#abc0c4]"><td className="px-5 py-3.5 font-bold text-[#d4e3e5]">{feature.label}</td><td className="mono px-5 py-3.5">{feature.baseline} {feature.unit}</td><td className="mono px-5 py-3.5 text-[#d8efec]">{feature.current} {feature.unit}</td><td className={`mono px-5 py-3.5 ${Math.abs(feature.delta) > 20 ? "text-[#ffb875]" : "text-[#85ddbb]"}`}>{feature.delta > 0 ? "+" : ""}{feature.delta}%</td><td className="px-5 py-3.5"><span className={`rounded border px-2 py-1 text-[9px] font-bold ${Math.abs(feature.delta) > 20 ? "border-[#ffb454]/20 bg-[#ffb454]/10 text-[#ffc980]" : "border-[#5ee6d0]/15 bg-[#5ee6d0]/[.07] text-[#83e0d1]"}`}>{Math.abs(feature.delta) > 20 ? "DEVIATING" : "WITHIN BAND"}</span></td></tr>)}</tbody></table></div></Panel></div>;
}

function AnomaliesPage({ anomalies, onAcknowledge, onResolve }: { anomalies: Anomaly[]; onAcknowledge: (id: string) => void; onResolve: (id: string) => void }) {
  const [filter, setFilter] = useState("all"); const [selected, setSelected] = useState<Anomaly | null>(null);
  const filtered = filter === "all" ? anomalies : anomalies.filter((a) => a.severity.toLowerCase() === filter);
  const { language } = useLanguage();
  return <div className="space-y-5"><div className="flex flex-wrap items-end justify-between gap-3"><div><div className="mono text-[10px] text-[#61939b]">DETECTION / REVIEW QUEUE</div><h2 className="mt-1 text-[24px] font-extrabold tracking-[-.05em]">{language === "ta" ? "முரண்பாடு நுண்ணறிவு" : "Anomaly Intelligence"}</h2><p className="mt-1 text-[11px] text-[#718d97]">Prioritized deviations requiring human investigation.</p></div><div className="flex gap-2"><button className="flex items-center gap-2 rounded-lg border border-white/[.1] bg-white/[.025] px-3 py-2 text-[10px] font-bold text-[#9eb8bd]"><ListFilter size={14} /> Export queue</button></div></div><div className="flex flex-wrap items-center gap-2"><span className="text-[10px] text-[#68838e]">Filter:</span>{["all", "critical", "high", "medium"].map((value) => <button key={value} onClick={() => setFilter(value)} className={`rounded-md border px-3 py-1.5 text-[10px] font-bold uppercase tracking-[.08em] ${filter === value ? "border-[#5ee6d0]/25 bg-[#5ee6d0]/10 text-[#a5ece2]" : "border-white/[.08] bg-white/[.02] text-[#718c95]"}`}>{value}</button>)}</div><Panel title="Detection queue" subtitle={`${filtered.length} records · AI findings are not definitive theft determinations`}><div className="overflow-x-auto"><table className="w-full min-w-[850px] text-left"><thead className="border-b border-white/[.06] text-[9px] uppercase tracking-[.15em] text-[#60808a]"><tr><th className="px-5 py-3">Timestamp</th><th className="px-5 py-3">Anomaly ID</th><th className="px-5 py-3">Location</th><th className="px-5 py-3">Type</th><th className="px-5 py-3">Deviation</th><th className="px-5 py-3">Risk</th><th className="px-5 py-3">Status</th><th className="px-5 py-3">Action</th></tr></thead><tbody className="divide-y divide-white/[.05]">{filtered.map((anomaly) => <tr key={anomaly.id} className="cursor-pointer text-[11px] text-[#a9bec2] transition-colors hover:bg-white/[.025]" onClick={() => setSelected(anomaly)}><td className="mono px-5 py-4 text-[#76939c]">{timeAgo(anomaly.timestamp)}</td><td className="mono px-5 py-4 font-bold text-[#d5e8e8]">{anomaly.id}</td><td className="px-5 py-4"><div className="font-bold text-[#c9dfe1]">{anomaly.location}</div><div className="text-[9px] text-[#66838d]">Chennai · Ambattur</div></td><td className="px-5 py-4 text-[#c2d7da]">{anomaly.type}</td><td className="mono px-5 py-4 text-[#ffbf79">+{anomaly.deviation}%</td><td className="px-5 py-4"><span className={`rounded border px-2 py-1 text-[9px] font-bold ${severityClass(anomaly.severity)}`}>{anomaly.risk} · {anomaly.severity}</span></td><td className="px-5 py-4 text-[10px]">{anomaly.status}</td><td className="px-5 py-4"><button onClick={(event) => { event.stopPropagation(); setSelected(anomaly); }} className="rounded-md border border-[#5ee6d0]/20 bg-[#5ee6d0]/[.06] px-2.5 py-1.5 text-[9px] font-bold text-[#9be8de]">View details</button></td></tr>)}</tbody></table></div></Panel>{selected && <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/65 p-4" onClick={() => setSelected(null)}><div className="w-full max-w-xl rounded-xl border border-white/[.1] bg-[#0b1822] panel-shine" onClick={(event) => event.stopPropagation()}><div className="flex items-start justify-between border-b border-white/[.07] p-5"><div><div className="mono text-[10px] text-[#6b929b]">{selected.id} · {timeAgo(selected.timestamp)}</div><h3 className="mt-1 text-[18px] font-extrabold text-[#e9f5f3]">{selected.type}</h3><p className="mt-1 text-[10px] text-[#76919a]">Suspicious location · {selected.location} / FDR-12 / TR-07</p></div><button onClick={() => setSelected(null)} className="rounded-md p-1 text-[#7d9aa2] hover:bg-white/5"><X size={17} /></button></div><div className="space-y-4 p-5"><div className="grid grid-cols-2 gap-3 sm:grid-cols-4"><div className="rounded-lg border border-white/[.07] bg-white/[.025] p-3"><div className="text-[9px] uppercase text-[#66828c]">Risk score</div><div className="mono mt-1 text-[22px] text-[#ffb979]">{selected.risk}<small className="text-[10px]">/100</small></div></div><div className="rounded-lg border border-white/[.07] bg-white/[.025] p-3"><div className="text-[9px] uppercase text-[#66828c]">Confidence</div><div className="mono mt-1 text-[22px] text-[#9ee6d8]">{Math.round(selected.confidence * 100)}<small className="text-[10px]">%</small></div></div><div className="rounded-lg border border-white/[.07] bg-white/[.025] p-3"><div className="text-[9px] uppercase text-[#66828c]">Anomaly score</div><div className="mono mt-1 text-[22px] text-[#ff9c9c]">{selected.anomalyScore}<small className="text-[10px]">/100</small></div></div><div className="rounded-lg border border-white/[.07] bg-white/[.025] p-3"><div className="text-[9px] uppercase text-[#66828c]">Deviation</div><div className="mono mt-1 text-[22px] text-[#ff9c9c]">+{selected.deviation}<small className="text-[10px]">%</small></div></div></div><div className="rounded-lg border border-[#ffb454]/20 bg-[#ffb454]/[.06] p-4"><div className="flex gap-2"><TriangleAlert size={15} className="mt-0.5 shrink-0 text-[#ffc779]" /><div><div className="text-[10px] font-bold text-[#ffd18f]">AI assessment · investigation required</div><p className="mt-1 text-[11px] leading-5 text-[#c4b38e]">{selected.description}</p></div></div></div><div><div className="text-[10px] font-bold uppercase tracking-[.12em] text-[#6f8e97]">Possible causes</div><div className="mt-2 flex flex-wrap gap-2">{selected.causes.map((cause) => <span key={cause} className="rounded border border-white/[.08] bg-white/[.025] px-2 py-1 text-[10px] text-[#a7bec2]">{cause}</span>)}</div></div><div className="rounded-lg border border-white/[.07] p-3"><div className="text-[10px] font-bold text-[#c4d9db]">Recommended investigation</div><p className="mt-1 text-[10px] leading-5 text-[#78939d]">{selected.recommendation}</p></div><div className="flex justify-end gap-2"><button onClick={() => { onAcknowledge(selected.id); setSelected(null); }} className="rounded-lg border border-[#5ee6d0]/20 bg-[#5ee6d0]/[.07] px-3 py-2 text-[10px] font-bold text-[#9ce9de]">Acknowledge</button><button onClick={() => { onResolve(selected.id); setSelected(null); }} className="rounded-lg bg-[#5ee6d0] px-3 py-2 text-[10px] font-extrabold text-[#04100f]">Mark resolved</button></div></div></div></div>}</div>;
}

function EnergyPage({ energy }: { energy: { supplied: number; accounted: number; difference: number; differencePercentage: number; trend: Array<{ day: string; supplied: number; accounted: number; losses: number }>; opportunities: string[] } }) {
  const { language } = useLanguage();
  return <div className="space-y-5"><div><div className="mono text-[10px] text-[#61939b]">ENERGY / BALANCE ENGINE</div><h2 className="mt-1 text-[24px] font-extrabold tracking-[-.05em]">{language === "ta" ? "ஆற்றல் நுண்ணறிவு" : "Energy Intelligence"}</h2><p className="mt-1 text-[11px] text-[#718d97]">Supply, accounted energy, and loss signals across the simulated network.</p></div><div className="grid grid-cols-2 gap-3 xl:grid-cols-4"><MetricCard label="Energy supplied" value={fmt(energy.supplied)} suffix="kWh" icon={ArrowUpRight} note="latest 24h window" tone="cyan" /><MetricCard label="Energy accounted" value={fmt(energy.accounted)} suffix="kWh" icon={Check} note="metered consumption" tone="green" /><MetricCard label="Energy difference" value={fmt(energy.difference)} suffix="kWh" icon={ArrowDownRight} note="requires reconciliation" tone="amber" /><MetricCard label="Difference percentage" value={energy.differencePercentage.toFixed(1)} suffix="%" icon={AlertTriangle} note="not a definitive theft finding" tone={energy.differencePercentage > 8 ? "amber" : "cyan"} /></div><div className="grid gap-5 xl:grid-cols-[minmax(0,1.4fr)_minmax(280px,.6fr)]"><Panel title="Daily energy trend" subtitle="Supply vs accounted energy · kWh"><div className="h-[315px] p-5"><ResponsiveContainer width="100%" height="100%"><BarChart data={energy.trend} margin={{ left: -20, right: 8, top: 10, bottom: 0 }}><CartesianGrid stroke="rgba(142,185,196,.08)" vertical={false} /><XAxis dataKey="day" tick={{ fill: "#65838d", fontSize: 9 }} tickLine={false} axisLine={false} /><YAxis tick={{ fill: "#65838d", fontSize: 9 }} tickLine={false} axisLine={false} /><Tooltip contentStyle={tooltipStyle} /><Bar dataKey="supplied" fill="#5ee6d0" radius={[4,4,0,0]} name="Supplied" /><Bar dataKey="accounted" fill="#587582" radius={[4,4,0,0]} name="Accounted" /></BarChart></ResponsiveContainer></div></Panel><Panel title="Investigation context" subtitle="Possible causes of energy difference"><div className="p-5"><div className="rounded-lg border border-[#ffb454]/20 bg-[#ffb454]/[.06] p-3 text-[10px] leading-5 text-[#d3b77e]">Energy imbalance detected — investigation required. ESI does not automatically classify an energy difference as theft.</div><ul className="mt-4 space-y-3">{["Technical losses", "Metering errors", "Communication problems", "Transformer losses", "Load estimation errors", "Possible unauthorized consumption"].map((item) => <li key={item} className="flex items-center gap-2 text-[10px] text-[#9ab2b7]"><span className="h-1.5 w-1.5 rounded-full bg-[#5ee6d0]" />{item}</li>)}</ul></div></Panel></div><Panel title="Energy conservation opportunities" subtitle="Prioritized from current balance patterns"><div className="grid gap-px bg-white/[.06] sm:grid-cols-2">{energy.opportunities.map((item, i) => <div key={item} className="flex gap-3 bg-[#0b1822] p-4"><span className="mono text-[11px] text-[#5ee6d0]">0{i + 1}</span><span className="text-[11px] text-[#adc2c5]">{item}</span></div>)}</div></Panel></div>;
}

function NetworkPage({ network, mode }: { network: { nodes: Node[]; hierarchy: Array<{ id: string; label: string; children: Array<{ id: string; label: string; children: Array<{ id: string; label: string; children: never[] }> }> }> }; mode: "tree" | "transformers" | "feeders" }) {
  const filtered = mode === "transformers" ? network.nodes.filter((n) => n.kind === "transformer") : mode === "feeders" ? network.nodes.filter((n) => n.kind === "feeder" || n.kind === "section") : network.nodes;
  const [open, setOpen] = useState<Record<string, boolean>>({ "CHN-SUB-01": true, "TR-07": true, "FDR-12": true });
  const nodeById = new Map(network.nodes.map((n) => [n.id, n]));
  function Tree({ item, depth = 0 }: { item: { id: string; label: string; children: Array<{ id: string; label: string; children: never[] }> | Array<{ id: string; label: string; children: Array<{ id: string; label: string; children: never[] }> }> }; depth?: number }) { const children = item.children ?? []; const n = nodeById.get(item.id); const expanded = open[item.id] ?? false; return <div><button onClick={() => setOpen((current) => ({ ...current, [item.id]: !expanded }))} className={`flex w-full items-center gap-2 rounded-lg px-3 py-2 text-left hover:bg-white/[.035] ${n?.status === "critical" ? "text-[#ff9898]" : n?.status === "warning" ? "text-[#ffc57b]" : "text-[#afc7ca]"}`} style={{ paddingLeft: `${12 + depth * 26}px` }}>{children.length ? (expanded ? <ChevronDown size={13} /> : <ChevronRight size={13} />) : <span className="w-[13px]" />}<span className={`h-1.5 w-1.5 rounded-full ${n ? dotClass(n.status) : "bg-[#5ee6d0]"}`} /><span className="text-[11px] font-semibold">{item.label}</span>{n && <span className="mono ml-auto text-[9px] text-[#5e7c85]">{n.load}% load</span>}</button>{expanded && children.map((child) => <Tree key={child.id} item={child} depth={depth + 1} />)}</div>; }
  const { language } = useLanguage();
  return <div className="space-y-5"><div><div className="mono text-[10px] text-[#61939b]">NETWORK / TOPOLOGY</div><h2 className="mt-1 text-[24px] font-extrabold tracking-[-.05em]">{mode === "tree" ? "Network Intelligence" : mode === "transformers" ? "Transformer Intelligence" : "Feeder & Section Monitoring"}</h2><p className="mt-1 text-[11px] text-[#718d97]">Trace energy flow from substation to the monitored section.</p></div>{mode === "tree" ? <div className="grid gap-5 xl:grid-cols-[minmax(0,.85fr)_minmax(0,1.15fr)]"><Panel title="Network hierarchy" subtitle="Suspicious nodes are highlighted by live telemetry"><div className="p-3">{network.hierarchy.map((item) => <Tree key={item.id} item={item} />)}</div></Panel><Panel title="Selected network context" subtitle="The highlighted route is the current investigation path"><div className="p-5"><div className="flex flex-wrap items-center gap-2 text-[10px] font-bold text-[#b9d1d2]"><span className="rounded border border-[#5ee6d0]/20 bg-[#5ee6d0]/[.07] px-2 py-1">CHN-SUB-01</span><ChevronRight size={13} className="text-[#5c7d86]" /><span className="rounded border border-[#5ee6d0]/20 bg-[#5ee6d0]/[.07] px-2 py-1">TR-07</span><ChevronRight size={13} className="text-[#5c7d86]" /><span className="rounded border border-[#ffb454]/25 bg-[#ffb454]/[.08] px-2 py-1 text-[#ffd08b]">FDR-12</span><ChevronRight size={13} className="text-[#5c7d86]" /><span className="rounded border border-[#ff6b6b]/25 bg-[#ff6b6b]/[.08] px-2 py-1 text-[#ffadad]">SEC-31</span></div><div className="mt-7 grid gap-3 sm:grid-cols-2">{network.nodes.filter((n) => ["TR-07", "FDR-12", "SEC-31"].includes(n.id)).map((n) => <div key={n.id} className="rounded-xl border border-white/[.07] bg-white/[.025] p-4"><div className="flex justify-between"><span className="mono text-[11px] font-bold text-[#d1e4e4]">{n.id}</span><span className={`h-2 w-2 rounded-full ${dotClass(n.status)}`} /></div><div className="mt-1 text-[10px] text-[#718e97]">{n.name}</div><div className="mt-4 grid grid-cols-2 gap-3"><div><div className="text-[9px] text-[#5f7c85]">Voltage</div><div className="mono mt-1 text-[14px] text-[#c7e1df]">{n.voltage}V</div></div><div><div className="text-[9px] text-[#5f7c85]">Load</div><div className="mono mt-1 text-[14px] text-[#c7e1df]">{n.load}%</div></div></div></div>)}</div></div></Panel></div> : <Panel title={`${filtered.length} monitored assets`} subtitle="Live node cards · click map from the navigation for spatial context"><div className="grid gap-3 p-5 sm:grid-cols-2 xl:grid-cols-3">{filtered.map((node) => <div key={node.id} className="rounded-xl border border-white/[.08] bg-white/[.025] p-4"><div className="flex items-start justify-between"><div><div className="mono text-[12px] font-bold text-[#d4e8e7]">{node.id}</div><div className="mt-1 text-[10px] text-[#738f98]">{node.name} · {node.location}</div></div><span className={`h-2 w-2 rounded-full ${dotClass(node.status)}`} /></div><div className="mt-5 grid grid-cols-3 gap-2"><div><div className="text-[8px] uppercase tracking-[.1em] text-[#5f7d87]">Load</div><div className="mono mt-1 text-[15px] text-[#d9eeeb]">{node.load}%</div></div><div><div className="text-[8px] uppercase tracking-[.1em] text-[#5f7d87]">Power</div><div className="mono mt-1 text-[15px] text-[#d9eeeb]">{node.power}</div></div><div><div className="text-[8px] uppercase tracking-[.1em] text-[#5f7d87]">Risk</div><div className={`mono mt-1 text-[15px] ${node.risk > 60 ? "text-[#ff9b9b]" : node.risk > 30 ? "text-[#ffc479]" : "text-[#99ded1]"}`}>{node.risk}</div></div></div><div className="mt-4 h-1 rounded-full bg-[#1e353d]"><div className={`h-full rounded-full ${node.status === "critical" ? "bg-[#ff6b6b]" : node.status === "warning" ? "bg-[#ffb454]" : "bg-[#5ee6d0]"}`} style={{ width: `${node.load}%` }} /></div></div>)}</div></Panel>}</div>;
}

function MapPage({ nodes }: { nodes: Node[] }) {
  const { language } = useLanguage();
  const tamil = language === "ta";
  const assets = [
    { id: "CHN-SUB-01", label: "Chennai North", district: "Chennai", kind: "substation", x: 78, y: 14, spec: "230 / 110 kV", capacity: "2 × 150 MVA", equipment: "AIS switchyard" },
    { id: "TR-07", label: "Salem Central", district: "Salem", kind: "transformer", x: 57, y: 40, spec: "110 / 33 kV", capacity: "63 MVA", equipment: "ONAN transformer" },
    { id: "CBE-SUB-02", label: "Coimbatore East", district: "Coimbatore", kind: "substation", x: 38, y: 58, spec: "230 / 110 kV", capacity: "2 × 100 MVA", equipment: "GIS switchyard" },
    { id: "TR-12", label: "Tiruchirappalli", district: "Trichy", kind: "transformer", x: 61, y: 57, spec: "110 / 33 kV", capacity: "63 MVA", equipment: "OLTC transformer" },
    { id: "SEC-31", label: "Madurai South", district: "Madurai", kind: "section", x: 53, y: 72, spec: "33 / 11 kV", capacity: "20 MVA", equipment: "Feeder section" },
    { id: "SEC-18", label: "Tirunelveli", district: "Tirunelveli", kind: "section", x: 47, y: 89, spec: "33 / 11 kV", capacity: "16 MVA", equipment: "Feeder section" },
    { id: "SEC-30", label: "Cuddalore", district: "Cuddalore", kind: "section", x: 70, y: 41, spec: "33 / 11 kV", capacity: "20 MVA", equipment: "Feeder section" },
  ];
  const [selectedId, setSelectedId] = useState("SEC-31");
  const selectedAsset = assets.find((asset) => asset.id === selectedId) ?? assets[0];
  const selectedTelemetry = nodes.find((node) => node.id === selectedAsset.id) ?? nodes[0];
  const statusColor = (status: Node["status"]) => status === "critical" ? "#ff6b6b" : status === "warning" ? "#ffb454" : "#5ee6d0";
  return <div className="space-y-5"><div className="flex flex-wrap items-end justify-between gap-3"><div><div className="mono text-[10px] text-[#61939b]">GIS / TAMIL NADU / SIMULATED COORDINATES</div><h2 className="mt-1 text-[24px] font-extrabold tracking-[-.05em]">{tamil ? "தமிழ்நாடு புவியியல் வலையமைப்பு" : "Tamil Nadu geographic network"}</h2><p className="mt-1 text-[11px] text-[#718d97]">{tamil ? "துணை மின் நிலையங்கள் மற்றும் மின்மாற்றி விவரங்கள்" : "Substations, transformers, feeders and live asset specifications"}</p></div><div className="flex gap-2"><StatusChip tone="amber">SIMULATED GIS</StatusChip><StatusChip><Globe2 size={12} /> 7 ASSETS MAPPED</StatusChip></div></div><div className="grid gap-5 xl:grid-cols-[minmax(0,1.45fr)_380px]"><Panel className="min-h-[630px]" title={tamil ? "தமிழ்நாடு வலையமைப்பு வரைபடம்" : "Tamil Nadu grid map"} subtitle="Illustrative geography · prototype telemetry only" action={<div className="flex items-center gap-2 text-[9px] font-bold uppercase tracking-[.1em] text-[#6f8b95]"><span className="h-1.5 w-1.5 rounded-full bg-[#5ee6d0]" />Live view</div>}><div className="geo-map-shell relative min-h-[545px] overflow-hidden rounded-b-xl"><div className="geo-map-grid absolute inset-0" /><svg viewBox="0 0 100 100" className="absolute inset-[5%_8%] h-[90%] w-[84%] overflow-visible" role="img" aria-label="Stylized Tamil Nadu geographic network map"><defs><linearGradient id="tnLand" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stopColor="#143f54" /><stop offset="100%" stopColor="#0b263d" /></linearGradient><filter id="tnGlow"><feGaussianBlur stdDeviation="1.6" /></filter></defs><path className="tn-state-glow" d="M64 4 L77 7 83 17 80 26 88 35 78 44 73 52 68 63 61 73 58 84 49 97 42 89 39 78 33 69 30 58 25 48 28 39 34 31 38 21 47 15 55 8 Z" /><path className="tn-state-outline" d="M64 4 L77 7 83 17 80 26 88 35 78 44 73 52 68 63 61 73 58 84 49 97 42 89 39 78 33 69 30 58 25 48 28 39 34 31 38 21 47 15 55 8 Z" fill="url(#tnLand)" /><path d="M55 8 L60 20 56 31 61 43 57 54 61 68 52 78 49 97" className="tn-route" /><path d="M30 58 L57 54 73 52 83 35" className="tn-route tn-route-warm" /><path d="M39 78 L57 54 68 63" className="tn-route" /><text x="47" y="28" className="tn-label">NORTH</text><text x="44" y="54" className="tn-label">CENTRAL</text><text x="43" y="84" className="tn-label">SOUTH</text></svg>{assets.map((asset) => { const telemetry = nodes.find((node) => node.id === asset.id); const status = telemetry?.status ?? "normal"; const chosen = asset.id === selectedId; return <button key={asset.id} onClick={() => setSelectedId(asset.id)} style={{ left: `${asset.x}%`, top: `${asset.y}%`, "--asset-color": statusColor(status) } as React.CSSProperties} className={`geo-asset-marker absolute -translate-x-1/2 -translate-y-1/2 ${chosen ? "is-selected" : ""}`}><span className="geo-asset-dot"><span>{asset.kind === "transformer" ? "TR" : asset.kind === "substation" ? "SS" : "F"}</span></span><span className="geo-asset-label"><strong>{asset.id}</strong><small>{asset.district}</small></span></button>; })}<div className="absolute left-4 top-4 rounded-lg border border-[#5ee6d0]/15 bg-[#071722]/85 px-3 py-2 backdrop-blur"><div className="flex items-center gap-2 text-[9px] font-bold uppercase tracking-[.14em] text-[#a9eee1]"><MapPinned size={12} /> Tamil Nadu / India</div><div className="mono mt-1 text-[8px] text-[#658b94]">11.1271° N · 78.6569° E</div></div><div className="absolute bottom-4 left-4 flex flex-wrap gap-3 rounded-lg border border-white/[.08] bg-[#07131b]/90 px-3 py-2 text-[9px] text-[#79949d]"><span className="flex items-center gap-1.5"><i className="h-2 w-2 rounded-full bg-[#5ee6d0]" />Normal</span><span className="flex items-center gap-1.5"><i className="h-2 w-2 rounded-full bg-[#ffb454]" />Warning</span><span className="flex items-center gap-1.5"><i className="h-2 w-2 rounded-full bg-[#ff6b6b]" />Critical</span><span className="border-l border-white/10 pl-3 text-[#5ee6d0]">Click an asset</span></div></div></Panel><div className="space-y-5"><Panel title={tamil ? "சொத்து விவரக்குறிப்பு" : "Asset specification"} subtitle={`${selectedAsset.label} · ${selectedAsset.district}`}><div className="p-5"><div className="flex items-start justify-between"><div><div className="mono text-[21px] font-medium text-[#e1f0ed]">{selectedAsset.id}</div><div className="mt-1 text-[10px] text-[#78939d]">{selectedAsset.kind === "substation" ? "Substation" : selectedAsset.kind === "transformer" ? "Power transformer" : "Distribution section"}</div></div><span className="rounded border px-2 py-1 text-[9px] font-bold uppercase" style={{ color: statusColor(selectedTelemetry?.status ?? "normal"), borderColor: `${statusColor(selectedTelemetry?.status ?? "normal")}55`, background: `${statusColor(selectedTelemetry?.status ?? "normal")}12` }}>{selectedTelemetry?.status ?? "normal"}</span></div><div className="mt-5 rounded-xl border border-[#5ee6d0]/15 bg-[#5ee6d0]/[.04] p-4"><div className="text-[9px] font-bold uppercase tracking-[.14em] text-[#6f929a]">Primary rating</div><div className="mono mt-2 text-[22px] text-[#dff5f0]">{selectedAsset.spec}</div><div className="mt-1 text-[10px] text-[#7b9aa1]">{selectedAsset.capacity} · {selectedAsset.equipment}</div></div><div className="mt-4 grid grid-cols-2 gap-3">{[["Voltage", `${selectedTelemetry?.voltage ?? "—"} V`], ["Current", `${selectedTelemetry?.current ?? "—"} A`], ["Power", `${selectedTelemetry?.power ?? "—"} kW`], ["Load", `${selectedTelemetry?.load ?? "—"}%`], ["Risk score", `${selectedTelemetry?.risk ?? "—"}/100`], ["Coordinates", `${selectedAsset.x.toFixed(1)}° / ${selectedAsset.y.toFixed(1)}°`]].map(([label, value]) => <div key={label} className="rounded-lg border border-white/[.07] bg-white/[.025] p-3"><div className="text-[9px] uppercase tracking-[.11em] text-[#62808a]">{label}</div><div className="mono mt-1 text-[12px] text-[#cfe4e3]">{value}</div></div>)}</div></div></Panel><Panel title={tamil ? "துணை மின் நிலைய பதிவு" : "Substation & transformer register"} subtitle="Mapped assets in the prototype region"><div className="divide-y divide-white/[.06]">{assets.slice(0, 5).map((asset) => { const telemetry = nodes.find((node) => node.id === asset.id); return <button key={asset.id} onClick={() => setSelectedId(asset.id)} className={`flex w-full items-center gap-3 px-4 py-3 text-left transition ${asset.id === selectedId ? "bg-[#5ee6d0]/[.07]" : "hover:bg-white/[.035]"}`}><span className="grid h-7 w-7 place-items-center rounded-md border border-[#5ee6d0]/20 bg-[#5ee6d0]/[.06] text-[8px] font-black text-[#76e4d4]">{asset.kind === "transformer" ? "TR" : "SS"}</span><span className="min-w-0 flex-1"><span className="block text-[10px] font-bold text-[#c8dcdf]">{asset.id} · {asset.district}</span><span className="block truncate text-[9px] text-[#6f8b95]">{asset.spec} · {asset.capacity}</span></span><span className="h-2 w-2 rounded-full" style={{ background: statusColor(telemetry?.status ?? "normal") }} /></button>; })}</div></Panel></div></div></div>;
}
function AlertsPage({ anomalies, onNavigate }: { anomalies: Anomaly[]; onNavigate: (id: NavId) => void }) {
  const { language } = useLanguage();
  return <div className="space-y-5"><div className="flex items-end justify-between"><div><div className="mono text-[10px] text-[#61939b]">OPERATE / NOTIFICATIONS</div><h2 className="mt-1 text-[24px] font-extrabold tracking-[-.05em]">{language === "ta" ? "ESI எச்சரிக்கை மையம்" : "ESI Alert Centre"}</h2><p className="mt-1 text-[11px] text-[#718d97]">Human-in-the-loop alerts generated from anomaly analysis.</p></div><StatusChip tone={anomalies.some((a) => a.severity === "CRITICAL") ? "red" : "green"}>{anomalies.length} OPEN ITEMS</StatusChip></div><div className="grid gap-4 lg:grid-cols-2">{anomalies.map((anomaly) => <div key={anomaly.id} className={`rounded-xl border p-5 ${anomaly.severity === "CRITICAL" ? "border-[#ff6b6b]/25 bg-[#301d25]/40" : "border-[#ffb454]/20 bg-[#281f18]/40"}`}><div className="flex items-start justify-between"><div className="flex gap-3"><div className={`grid h-9 w-9 place-items-center rounded-lg ${anomaly.severity === "CRITICAL" ? "bg-[#ff6b6b]/10 text-[#ff8585]" : "bg-[#ffb454]/10 text-[#ffc275]"}`}><Bell size={16} /></div><div><div className="text-[12px] font-bold text-[#e3eded]">{anomaly.type}</div><div className="mt-1 mono text-[10px] text-[#a47f69]">{anomaly.location} · {timeAgo(anomaly.timestamp)}</div></div></div><span className={`rounded border px-2 py-1 text-[9px] font-bold ${severityClass(anomaly.severity)}`}>{anomaly.severity}</span></div><div className="mt-5 flex items-end justify-between"><div><div className="text-[9px] uppercase tracking-[.12em] text-[#7c8e8e]">Risk score</div><div className="mono mt-1 text-[28px] text-[#ffd08d]">{anomaly.risk}<small className="text-[11px] text-[#9e8c76]">/100</small></div></div><button onClick={() => onNavigate("anomalies")} className="rounded-lg border border-[#ffb454]/25 bg-[#ffb454]/[.07] px-3 py-2 text-[10px] font-bold text-[#ffd08f]">Investigation required</button></div></div>)}</div></div>;
}

function SimulationPage({ activeMode, onSimulate, busy }: { activeMode: string; onSimulate: (scenario: SimScenario) => void; busy: boolean }) {
  const actions: Array<{ id: SimScenario; title: string; description: string; icon: LucideIcon; tone: "green" | "amber" | "red" | "cyan" }> = [
    { id: "normal", title: "Normal Operation", description: "Reset every reading and visualization to the learned baseline.", icon: Check, tone: "green" },
    { id: "abnormal-load", title: "Abnormal Load", description: "Inject a sudden demand signature into SEC-31.", icon: Activity, tone: "amber" },
    { id: "potential-theft", title: "Potential Electricity Theft", description: "Simulate a suspicious route-level energy accounting pattern.", icon: ShieldAlert, tone: "red" },
    { id: "meter-anomaly", title: "Potential Meter Tampering", description: "Create a suspicious metering deviation for investigation.", icon: ShieldAlert, tone: "red" },
    { id: "transformer-anomaly", title: "Transformer Anomaly", description: "Push TR-07 toward an abnormal operating profile.", icon: Thermometer, tone: "red" },
    { id: "night-consumption", title: "Unusual Night Consumption", description: "Raise the overnight demand profile above baseline.", icon: TimerReset, tone: "amber" },
    { id: "energy-imbalance", title: "Energy Imbalance", description: "Create a supply-vs-accounted energy gap.", icon: Zap, tone: "amber" },
  ];
  const colors = { green: "border-[#62d99b]/20 bg-[#62d99b]/[.05] text-[#91e8b7]", amber: "border-[#ffb454]/20 bg-[#ffb454]/[.05] text-[#ffd086]", red: "border-[#ff6b6b]/20 bg-[#ff6b6b]/[.05] text-[#ffabab]", cyan: "border-[#5ee6d0]/20 bg-[#5ee6d0]/[.05] text-[#a4eee5]" };
  const { language } = useLanguage();
  return <div className="space-y-5"><div className="flex flex-wrap items-end justify-between gap-3"><div><div className="mono text-[10px] text-[#61939b]">OPERATE / CONTROLLED SCENARIOS</div><h2 className="mt-1 text-[24px] font-extrabold tracking-[-.05em]">{language === "ta" ? "ESI உருவகப்படுத்தல் மையம்" : "ESI Simulation Centre"}</h2><p className="mt-1 text-[11px] text-[#718d97]">Every scenario updates the live backend state across all intelligence views.</p></div><StatusChip tone={activeMode === "normal" ? "green" : "amber"}><span className="h-1.5 w-1.5 rounded-full bg-current" /> {activeMode.replaceAll("-", " ").toUpperCase()}</StatusChip></div><Panel title="Choose a scenario" subtitle="SIMULATED DATA · no real electricity infrastructure is connected"><div className="grid gap-3 p-5 sm:grid-cols-2 xl:grid-cols-3">{actions.map((action) => { const Icon = action.icon; const selected = activeMode === action.id; return <button key={action.id} disabled={busy} onClick={() => onSimulate(action.id)} className={`group rounded-xl border p-4 text-left transition-all hover:-translate-y-0.5 ${selected ? colors[action.tone] : "border-white/[.08] bg-white/[.02] text-[#afc5c7] hover:border-white/[.16]"}`}><div className="flex items-start justify-between"><span className={`grid h-9 w-9 place-items-center rounded-lg ${selected ? "bg-white/[.08]" : "bg-white/[.05] text-[#77939b]"}`}><Icon size={16} /></span>{selected && <Check size={15} />}</div><div className="mt-5 text-[12px] font-bold">{action.title}</div><div className="mt-2 text-[10px] leading-5 text-[#78939c]">{action.description}</div><div className="mt-4 flex items-center gap-1 text-[9px] font-bold uppercase tracking-[.12em] opacity-80">{busy && selected ? <RefreshCcw size={11} className="animate-spin" /> : <ArrowUpRight size={11} />}Run simulation</div></button>; })}</div></Panel><Panel title="Synchronized live response" subtitle="One simulated event updates every ESI intelligence surface"><div className="grid gap-2 p-5 sm:grid-cols-2 lg:grid-cols-5">{["Electrical reading changes", "Signature comparison", "Anomaly intelligence", "Network path highlight", "Alert centre event"].map((step, i) => <div key={step} className="relative rounded-lg border border-white/[.07] bg-white/[.025] p-3"><div className="mono text-[10px] text-[#5ee6d0]">0{i + 1}</div><div className="mt-2 text-[10px] font-bold text-[#b8ced1]">{step}</div>{i < 4 && <ChevronRight size={14} className="absolute -right-3 top-5 z-10 hidden text-[#40616a] lg:block" />}</div>)}</div></Panel><div className="rounded-xl border border-[#ffb454]/20 bg-[#ffb454]/[.06] p-4 text-[10px] leading-5 text-[#cbb887]"><TriangleAlert size={14} className="mr-2 inline text-[#ffc375]" />All outputs are simulated. ESI never independently proves electricity theft or meter tampering; results are possible anomalies requiring authorized field investigation.</div></div>;
}

function ReportsPage({ summary, anomalies }: { summary: Summary; anomalies: Anomaly[] }) {
  const download = () => { const body = [`ESI INTELLIGENCE REPORT`, `Generated: ${new Date().toLocaleString()}`, `Data mode: SIMULATED NETWORK DATA`, ``, `NETWORK OVERVIEW`, `Network health: ${summary.networkHealth}%`, `Substations: ${summary.substations}`, `Transformers: ${summary.transformers}`, `Feeders: ${summary.feeders}`, `Sections: ${summary.sections}`, ``, `ANOMALIES`, ...anomalies.map((a) => `${a.id} | ${a.location} | ${a.type} | Risk ${a.risk} | ${a.status}`), ``, `LIMITATION`, `ESI is a research and hackathon prototype using simulated electrical data. It does not independently establish electricity theft.`].join("\n"); const url = URL.createObjectURL(new Blob([body], { type: "text/plain" })); const anchor = document.createElement("a"); anchor.href = url; anchor.download = "esi-intelligence-report.txt"; anchor.click(); URL.revokeObjectURL(url); toast.success("Intelligence report downloaded"); };
  const { language } = useLanguage();
  return <div className="space-y-5"><div className="flex flex-wrap items-end justify-between gap-3"><div><div className="mono text-[10px] text-[#61939b]">OPERATE / REPORTING</div><h2 className="mt-1 text-[24px] font-extrabold tracking-[-.05em]">{language === "ta" ? "ESI நுண்ணறிவு அறிக்கைகள்" : "ESI Intelligence Reports"}</h2><p className="mt-1 text-[11px] text-[#718d97]">A concise operating picture for investigation planning.</p></div><button onClick={download} className="flex items-center gap-2 rounded-lg bg-[#5ee6d0] px-3 py-2 text-[10px] font-extrabold text-[#04100f]"><Download size={14} /> Download report</button></div><div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_320px]"><Panel title="Report preview" subtitle={`ESI Intelligence Report · ${new Date().toLocaleDateString()}`}><div className="space-y-5 p-5"><div className="flex items-start justify-between border-b border-white/[.07] pb-4"><div><div className="text-[17px] font-extrabold text-[#e1efed]">Electric Signature Intelligence</div><div className="mt-1 text-[10px] text-[#76929a]">Network overview and anomaly investigation brief</div></div><StatusChip>SIMULATED DATA</StatusChip></div><div className="grid grid-cols-2 gap-3 sm:grid-cols-4">{[["Health", `${summary.networkHealth}%`], ["Anomalies", String(anomalies.length)], ["Energy gap", `${summary.energyImbalance}%`], ["Critical", String(summary.criticalAlerts)]].map(([label, value]) => <div key={label} className="rounded-lg border border-white/[.07] bg-white/[.025] p-3"><div className="text-[9px] uppercase text-[#62808a]">{label}</div><div className="mono mt-1 text-[17px] text-[#d5e9e6]">{value}</div></div>)}</div><div><div className="mb-3 text-[10px] font-bold uppercase tracking-[.12em] text-[#71909a]">Detected anomalies</div><div className="space-y-2">{anomalies.map((a) => <div key={a.id} className="flex items-center justify-between rounded-lg border border-white/[.06] bg-white/[.02] px-3 py-2.5"><div><span className="mono mr-2 text-[10px] text-[#8bb7b5]">{a.id}</span><span className="text-[10px] text-[#bfced0]">{a.type} · {a.location}</span></div><span className={`rounded border px-2 py-1 text-[9px] font-bold ${severityClass(a.severity)}`}>{a.risk}</span></div>)}</div></div><div className="rounded-lg border border-[#ffb454]/20 bg-[#ffb454]/[.05] p-3 text-[10px] leading-5 text-[#c8b786]">Recommended investigation areas should be validated with real utility data, authorized field inspection, and operational procedures.</div></div></Panel><Panel title="Risk distribution" subtitle="Current queue"><div className="flex items-center justify-center p-5"><div className="h-[210px] w-full"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={[{ name: "Low", value: 18, color: "#5ee6d0" }, { name: "Medium", value: 7, color: "#dbc15a" }, { name: "High", value: 3, color: "#ffb454" }, { name: "Critical", value: summary.criticalAlerts, color: "#ff6b6b" }]} dataKey="value" innerRadius={57} outerRadius={77} paddingAngle={4}>{["#5ee6d0", "#dbc15a", "#ffb454", "#ff6b6b"].map((color) => <Cell key={color} fill={color} />)}</Pie><Tooltip contentStyle={tooltipStyle} /></PieChart></ResponsiveContainer></div></div><div className="space-y-2 border-t border-white/[.06] p-5">{[["Low", "#5ee6d0", "18"], ["Medium", "#dbc15a", "07"], ["High", "#ffb454", "03"], ["Critical", "#ff6b6b", String(summary.criticalAlerts).padStart(2, "0")]].map(([label, color, value]) => <div key={label} className="flex items-center justify-between text-[10px]"><span className="flex items-center gap-2 text-[#839da4]"><i className="h-2 w-2 rounded-full" style={{ background: color }} />{label}</span><span className="mono text-[#c9dedd]">{value}</span></div>)}</div></Panel></div></div>;
}

function SettingsPage({ summary }: { summary: Summary }) {
  const { language } = useLanguage();
  const isTamil = language === "ta";
  return <div className="space-y-5"><div><div className="mono text-[10px] text-[#61939b]">SYSTEM / CONFIGURATION</div><h2 className="mt-1 text-[24px] font-extrabold tracking-[-.05em]">{isTamil ? "அமைப்புகள்" : "Settings"}</h2><p className="mt-1 text-[11px] text-[#718d97]">{isTamil ? "முன்மாதிரி சூழல், AI மாதிரி மற்றும் செயல்பாட்டு இணைப்புகள்." : "Prototype environment, AI model, and operating context."}</p></div><div className="grid gap-5 lg:grid-cols-2"><Panel title={isTamil ? "அமைப்பு தகவல்" : "System information"}><div className="divide-y divide-white/[.06]">{[[isTamil ? "AI மாதிரி" : "AI model", "Isolation Forest"], [isTamil ? "தரவு முறை" : "Data mode", isTamil ? "உருவகப்படுத்தல்" : "Simulation"], [isTamil ? "சூழல்" : "Environment", isTamil ? "முன்மாதிரி" : "Prototype"], [isTamil ? "பின்தளம்" : "Backend", isTamil ? "இணைக்கப்பட்டது" : "Connected"], [isTamil ? "தரவுத்தளம்" : "Database", isTamil ? "Schema தயார்" : "Schema ready"], [isTamil ? "வன்பொருள்" : "Hardware", summary.hardware.connected ? "ESP32 connected" : "ESP32 offline"]].map(([label, value]) => <div key={label} className="flex items-center justify-between px-5 py-4"><span className="text-[11px] text-[#7f9ba3]">{label}</span><span className="flex items-center gap-2 text-[11px] font-bold text-[#c4dbdc]"><span className="h-1.5 w-1.5 rounded-full bg-[#5ee6d0]" />{value}</span></div>)}</div></Panel><Panel title={isTamil ? "பாதுகாப்பு மற்றும் வரம்புகள்" : "Safety & limitations"}><div className="space-y-4 p-5 text-[11px] leading-6 text-[#8da7ad]"><p>{isTamil ? "ESI உருவகப்படுத்தப்பட்ட மின் தரவைப் பயன்படுத்தும் ஆராய்ச்சி மற்றும் ஹேக்கத்தான் முன்மாதிரி. இது நேரடி மின்விநியோக வலையமைப்புடன் இணைக்கப்படவில்லை; மின்திருட்டை தனியாக நிரூபிக்காது." : "ESI is a research and hackathon prototype using simulated electrical data. It is not connected to a live electricity distribution grid and does not independently establish electricity theft."}</p><p>{isTamil ? "உண்மையான பயன்பாட்டிற்கு சரிபார்க்கப்பட்ட பயன்பாட்டு தரவு, இணையப் பாதுகாப்பு கட்டுப்பாடுகள், ஒழுங்குமுறை அனுமதி மற்றும் அதிகாரப்பூர்வ பயன்பாட்டு அமைப்புகளுடன் ஒருங்கிணைப்பு தேவை." : "Real-world deployment would require validated utility data, cybersecurity controls, regulatory approval, field verification, and integration with authorized utility systems."}</p><p className="rounded-lg border border-[#ffb454]/20 bg-[#ffb454]/[.06] p-3 text-[#c9b987]">{isTamil ? "வன்பொருள் பாதுகாப்பு: குறைந்த மின்னழுத்த DC கூறுகளை மட்டும் பயன்படுத்தவும். 230V AC மின்சாரத்துடன் நேரடியாக இணைக்க வேண்டாம்." : "Hardware safety: use low-voltage DC components only. Never connect development-board circuitry directly to 230V AC mains."}</p></div></Panel></div><Panel title={isTamil ? "அதிகாரப்பூர்வ சேவை ஒருங்கிணைப்பு" : "Official service collaboration readiness"} subtitle={isTamil ? "அங்கீகரிக்கப்பட்ட API அல்லது MoU இல்லாமல் அதிகாரப்பூர்வ இணைப்பு என்று இந்த முன்மாதிரி கூறாது." : "This prototype does not claim official integration without an authorized API or MoU."}><div className="grid gap-3 p-5 md:grid-cols-3"><a className="rounded-xl border border-[#1d63a9]/20 bg-[#1d63a9]/[.05] p-4 transition hover:border-[#1d63a9]/40" href="https://www.tnpdcl.org/en/tnpdcl/" target="_blank" rel="noreferrer"><div className="flex items-center justify-between"><Landmark size={18} className="text-[#1d63a9]" /><ExternalLink size={13} className="text-[#1d63a9]" /></div><div className="mt-4 text-[12px] font-bold text-[#18334d]">TNPDCL</div><div className="mt-1 text-[10px] text-[#536a7e]">{isTamil ? "அதிகாரப்பூர்வ சேவைகள்" : "Official public services"}</div><div className="mt-3 text-[9px] font-bold uppercase tracking-[.12em] text-[#1d63a9]">{isTamil ? "வெளிப்புற போர்டல்" : "External portal"}</div></a><a className="rounded-xl border border-[#1d63a9]/20 bg-[#1d63a9]/[.05] p-4 transition hover:border-[#1d63a9]/40" href="https://www.tnebltd.org/en/tneb/" target="_blank" rel="noreferrer"><div className="flex items-center justify-between"><Landmark size={18} className="text-[#1d63a9]" /><ExternalLink size={13} className="text-[#1d63a9]" /></div><div className="mt-4 text-[12px] font-bold text-[#18334d]">TNEB Ltd</div><div className="mt-1 text-[10px] text-[#536a7e]">{isTamil ? "நிறுவன தகவல்" : "Organization information"}</div><div className="mt-3 text-[9px] font-bold uppercase tracking-[.12em] text-[#1d63a9]">{isTamil ? "வெளிப்புற போர்டல்" : "External portal"}</div></a><a className="rounded-xl border border-[#1d63a9]/20 bg-[#1d63a9]/[.05] p-4 transition hover:border-[#1d63a9]/40" href="https://www.tnebnet.org/qwp/qpay" target="_blank" rel="noreferrer"><div className="flex items-center justify-between"><Zap size={18} className="text-[#1d63a9]" /><ExternalLink size={13} className="text-[#1d63a9]" /></div><div className="mt-4 text-[12px] font-bold text-[#18334d]">Quick Pay</div><div className="mt-1 text-[10px] text-[#536a7e]">{isTamil ? "அதிகாரப்பூர்வ கட்டண போர்டல்" : "Official payment portal"}</div><div className="mt-3 text-[9px] font-bold uppercase tracking-[.12em] text-[#1d63a9]">{isTamil ? "வெளிப்புற போர்டல்" : "External portal"}</div></a></div></Panel></div>;
}

function PowerCommandRibbon({ summary, live, onNavigate }: { summary: Summary; live: { voltage: number; current: number; power: number; load: number }; onNavigate: (id: NavId) => void }) {
  const { language } = useLanguage();
  const tamil = language === "ta";
  const stable = !summary.activeAnomaly;
  return <section className="electric-command-panel relative overflow-hidden rounded-2xl border border-[#22d3ee]/25 p-5 shadow-[0_18px_50px_rgba(7,44,72,.20)] sm:p-6"><div className="electric-command-grid absolute inset-0" /><div className="electric-command-orb absolute -right-16 -top-24 h-64 w-64 rounded-full" /><div className="relative grid gap-6 xl:grid-cols-[1.1fr_1.7fr_.95fr] xl:items-center"><div><div className="flex items-center gap-2"><span className="h-2 w-2 rounded-full bg-cyan-300 shadow-[0_0_0_5px_rgba(34,211,238,.13),0_0_20px_rgba(34,211,238,.6)]" /><span className="mono text-[9px] font-bold tracking-[.22em] text-cyan-300">LIVE GRID PULSE</span><span className="rounded-full border border-cyan-300/20 bg-cyan-300/10 px-2 py-0.5 text-[8px] font-bold uppercase tracking-[.14em] text-cyan-200">{stable ? "Stable" : "Attention"}</span></div><div className="mt-3 flex items-end gap-2"><span className="mono text-[48px] font-medium leading-none tracking-[-.09em] text-white">{summary.networkHealth.toFixed(1)}</span><span className="mb-1 text-[17px] font-bold text-cyan-200">%</span></div><div className="mt-2 text-[11px] text-slate-300">{tamil ? "வலையமைப்பின் உடனடி நிலைத்தன்மை" : "Real-time network stability index"}</div><button onClick={() => onNavigate("map")} className="mt-4 inline-flex items-center gap-2 rounded-lg border border-cyan-200/25 bg-cyan-200/10 px-3 py-2 text-[10px] font-bold text-cyan-100 transition hover:-translate-y-0.5 hover:bg-cyan-200/15">{tamil ? "நேரடி வலையமைப்பைப் பார்க்க" : "Open live topology"}<ArrowUpRight size={13} /></button></div><div className="grid grid-cols-2 gap-3 sm:grid-cols-4"><div className="electric-reading"><span className="text-[9px] font-bold uppercase tracking-[.16em] text-slate-400">Voltage</span><span className="mono mt-3 block text-[22px] font-medium text-white">{live.voltage.toFixed(1)}<small className="ml-1 text-[10px] text-cyan-200">kV</small></span><span className="mt-1 block text-[9px] text-emerald-300">Nominal band</span></div><div className="electric-reading"><span className="text-[9px] font-bold uppercase tracking-[.16em] text-slate-400">Current</span><span className="mono mt-3 block text-[22px] font-medium text-white">{live.current.toFixed(1)}<small className="ml-1 text-[10px] text-cyan-200">A</small></span><span className="mt-1 block text-[9px] text-emerald-300">Within profile</span></div><div className="electric-reading"><span className="text-[9px] font-bold uppercase tracking-[.16em] text-slate-400">Power</span><span className="mono mt-3 block text-[22px] font-medium text-white">{live.power.toFixed(2)}<small className="ml-1 text-[10px] text-cyan-200">MW</small></span><span className="mt-1 block text-[9px] text-cyan-200">Live telemetry</span></div><div className="electric-reading"><span className="text-[9px] font-bold uppercase tracking-[.16em] text-slate-400">Load</span><span className="mono mt-3 block text-[22px] font-medium text-white">{live.load.toFixed(0)}<small className="ml-1 text-[10px] text-cyan-200">%</small></span><div className="mt-2 h-1 rounded-full bg-white/10"><div className="h-full rounded-full bg-gradient-to-r from-cyan-300 to-blue-400" style={{ width: `${live.load}%` }} /></div></div></div><div className="rounded-xl border border-white/10 bg-black/15 p-4 backdrop-blur-sm"><div className="flex items-center justify-between"><span className="mono text-[9px] font-bold tracking-[.18em] text-slate-400">ACTIVE FEED</span><Activity size={14} className="text-cyan-300" /></div><div className="mt-3 text-[21px] font-extrabold tracking-[-.05em] text-white">SEC-31</div><div className="mt-1 text-[10px] text-slate-300">TR-07 <span className="text-cyan-300">/</span> FDR-12</div><div className="mt-4 flex h-7 items-end gap-1">{[24, 39, 19, 34, 52, 28, 44, 36, 58, 31, 48, 64, 40, 28].map((height, index) => <span key={index} className="power-bar flex-1 rounded-t-sm bg-cyan-300/70" style={{ height: `${height}%`, animationDelay: `${index * 55}ms` }} />)}</div><div className="mt-2 flex items-center gap-1.5 text-[9px] text-emerald-300"><span className="h-1.5 w-1.5 rounded-full bg-emerald-300" />{stable ? "Signature within normal" : "Investigation required"}</div></div></div></section>;
}

